/* ❌ OLD: To override a component style you keep raising specificity:
   add more ancestors, more classes, !important. Every override makes
   the next one harder, and the cascade becomes unpredictable. */

.btn--primary {
  background: blue; /* base component rule */
}

/* ❌ OLD: override with a heavier selector to win */
.sidebar .widget .btn--primary {
  background: red;
}

/* Next override needs an even heavier selector or !important, and
   specificity defeats the intent of simple, maintainable selectors. */

/* ✅ NEW: Declare the layer order once. Any rule in a later layer wins
   over earlier layers regardless of specificity. */

@layer base, components, overrides; /* ✅ NEW: explicit priority order */

@layer base {
  .btn--primary {
    background: blue;
  }
}

@layer components {
  .btn {
    padding: 0.5rem 1rem;
  }
}

@layer overrides {
  .btn--primary {
    background: red; /* ✅ NEW: wins over base by layer order, not specificity */
  }
}

/* Simple selectors stay simple; the layer order does the prioritizing. */
